effect.shader:
void main(){
    vec2 px=1.0/acScreenSize;
    vec4 src=texture2DCv(inputImg.texture, acScreenNorm);
    vec3 c=src.a>0.0? src.rgb/src.a : src.rgb;
    float l =dot(texture2DCv(inputImg.texture, acScreenNorm-vec2(px.x,0.0)).rgb,vec3(0.333));
    float r =dot(texture2DCv(inputImg.texture, acScreenNorm+vec2(px.x,0.0)).rgb,vec3(0.333));
    float u =dot(texture2DCv(inputImg.texture, acScreenNorm-vec2(0.0,px.y)).rgb,vec3(0.333));
    float dn=dot(texture2DCv(inputImg.texture, acScreenNorm+vec2(0.0,px.y)).rgb,vec3(0.333));
    vec3 nrm=normalize(vec3((l-r)*height*10.0,(u-dn)*height*10.0,1.0));
    float grad=nrm.y*0.5+0.5;
    vec3 sky=vec3(0.55,0.7,0.95); vec3 ground=vec3(0.15,0.14,0.13);
    vec3 chrome=mix(ground, sky, smoothstep(0.35,0.65,grad));
    float hi=pow(clamp(dot(nrm, normalize(vec3(-0.5,0.6,0.6))),0.0,1.0),12.0);
    chrome += hi;
    gl_FragColor=vec4(mix(c, clamp(chrome,0.0,1.0), amount),1.0)*src.a;
}
